/**
 * Seed reference_models with common product categories for CAD Lab instant preview.
 * stl_url/step_url are null until actual reference files are uploaded to storage.
 */

ON CONFLICT (category) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  search_keywords = EXCLUDED.search_keywords,
  module_template = EXCLUDED.module_template,
  sort_order = EXCLUDED.sort_order,
  updated_at = now();
